require('dotenv').config();
const express=require('express');
const session=require('express-session');
const PgSession=require('connect-pg-simple')(session);
const {Pool}=require('pg');
const bcrypt=require('bcryptjs');
const helmet=require('helmet');
const rateLimit=require('express-rate-limit');
const multer=require('multer');
const crypto=require('crypto');
let nodemailer;
try{nodemailer=require('nodemailer');}catch(_e){nodemailer=null;}
const path=require('path');
const app=express();
// Render runs behind a trusted reverse proxy; this also makes secure cookies and rate limits work correctly.
app.set('trust proxy',1);
const PORT=process.env.PORT||3000;
if(!process.env.DATABASE_URL) console.warn('DATABASE_URL is missing. Add your Neon test database connection string in the deployment environment.');
if(!process.env.SESSION_SECRET||process.env.SESSION_SECRET.length<32) console.warn('Set SESSION_SECRET to a random string of at least 32 characters.');
const pool=new Pool({connectionString:process.env.DATABASE_URL,ssl:process.env.DATABASE_URL?.includes('neon.tech')?{rejectUnauthorized:false}:undefined,max:5,idleTimeoutMillis:30000,connectionTimeoutMillis:15000});
const q=(sql,params=[])=>pool.query(sql,params);
const now=()=>new Date().toISOString();
const today=()=>new Date().toISOString().slice(0,10);
const clean=(v,n=180)=>String(v??'').trim().slice(0,n);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₦'+Number(n||0).toLocaleString('en-NG');
const date=v=>{if(!v)return '—';const raw=String(v).slice(0,10);const d=/^\d{4}-\d{2}-\d{2}$/.test(raw)?new Date(raw+'T12:00:00'):new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('en-NG',{year:'numeric',month:'short',day:'numeric',timeZone:'Africa/Lagos'});};
const flash=(req,type,msg)=>req.session.flash={type,msg};
async function init(){
 await q(`CREATE TABLE IF NOT EXISTS admins(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL)`);
 await q(`CREATE TABLE IF NOT EXISTS students(id BIGSERIAL PRIMARY KEY,matric TEXT NOT NULL UNIQUE,full_name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,phone TEXT NOT NULL,department TEXT NOT NULL,level TEXT NOT NULL,courses TEXT NOT NULL,plan TEXT NOT NULL,password_hash TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),status TEXT NOT NULL DEFAULT 'No subscription',expiry_date DATE)`);
 await q(`CREATE TABLE IF NOT EXISTS payments(id BIGSERIAL PRIMARY KEY,student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,amount INTEGER NOT NULL,reference TEXT NOT NULL,evidence_data BYTEA,evidence_type TEXT NOT NULL,submitted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),status TEXT NOT NULL DEFAULT 'Pending',reviewed_at TIMESTAMPTZ,reviewed_by TEXT,admin_note TEXT,expiry_date DATE)`);
 await q(`CREATE TABLE IF NOT EXISTS audit_log(id BIGSERIAL PRIMARY KEY,actor TEXT,action TEXT,target TEXT,details TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE INDEX IF NOT EXISTS payments_student_idx ON payments(student_id)`);
 await q(`CREATE INDEX IF NOT EXISTS payments_status_idx ON payments(status)`);
 await q(`CREATE TABLE IF NOT EXISTS learning_materials(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,course TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',file_name TEXT NOT NULL,mime_type TEXT NOT NULL,file_data BYTEA,file_size INTEGER NOT NULL,uploaded_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`ALTER TABLE payments ADD COLUMN IF NOT EXISTS storage_path TEXT`);
 await q(`ALTER TABLE payments ALTER COLUMN evidence_data DROP NOT NULL`);
 await q(`ALTER TABLE learning_materials ADD COLUMN IF NOT EXISTS storage_path TEXT`);
 await q(`ALTER TABLE learning_materials ALTER COLUMN file_data DROP NOT NULL`);
 await q(`CREATE INDEX IF NOT EXISTS learning_materials_course_idx ON learning_materials(course,created_at DESC)`);
 await q(`CREATE TABLE IF NOT EXISTS announcements(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE TABLE IF NOT EXISTS tutorial_classes(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,course TEXT NOT NULL,class_date DATE NOT NULL,class_time TEXT NOT NULL,venue TEXT NOT NULL,details TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE TABLE IF NOT EXISTS support_requests(id BIGSERIAL PRIMARY KEY,student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,subject TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Open',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);

 if(process.env.ADMIN_EMAIL&&process.env.ADMIN_PASSWORD){const email=process.env.ADMIN_EMAIL.toLowerCase().trim();const exists=await q('SELECT id FROM admins WHERE email=$1',[email]);if(!exists.rowCount)await q('INSERT INTO admins(name,email,password_hash) VALUES($1,$2,$3)',[process.env.ADMIN_NAME||'FOCUS Admin',email,await bcrypt.hash(process.env.ADMIN_PASSWORD,12)]);}
}
async function audit(actor,action,target,details=''){await q('INSERT INTO audit_log(actor,action,target,details) VALUES($1,$2,$3,$4)',[actor,action,String(target),details]);}
async function sendRegistrationEmail(student){
 const fee=student.plan==='Monthly'?'₦7,000':'₦20,000';
 const subject='Your FOCUS TUTORIALS UI registration was successful';
 const html=`<div style="font-family:Arial,sans-serif;max-width:620px;margin:auto;padding:24px;color:#19243a;background:#f4f6fb"><div style="background:linear-gradient(120deg,#111d38,#315bce 68%,#8e587e);color:white;padding:28px;border-radius:18px"><div style="font-size:11px;letter-spacing:3px;color:#f0ce85;font-weight:bold">WELCOME TO</div><h1 style="margin:9px 0 0;font-size:28px;letter-spacing:.3px">FOCUS TUTORIALS UI</h1><p style="margin:8px 0 0;color:#e8edff">Academics Made Simple for Students.</p></div><div style="background:white;padding:26px;border-radius:18px;margin-top:16px"><h2 style="color:#172746">Registration successful!</h2><p>Hello ${esc(student.full_name)}, your student account has been created successfully. We are delighted to welcome you to the FOCUS learning community.</p><div style="background:#f2f5fc;padding:17px;border-radius:12px;line-height:1.95"><b>Matric number:</b> ${esc(student.matric)}<br><b>Gmail:</b> ${esc(student.email)}<br><b>Department:</b> ${esc(student.department)}<br><b>Level:</b> ${esc(student.level)}<br><b>Courses:</b> ${esc(student.courses)}<br><b>Plan:</b> ${esc(student.plan)}<br><b>Plan fee:</b> ${fee}</div><p>Sign in to your FOCUS TUTORIALS UI dashboard to submit your payment reference and receipt. Your subscription becomes active only after an administrator reviews and approves your payment.</p><p>Need help? WhatsApp support: <b>08152826270</b></p><p style="margin-top:25px"><b>FOCUS TUTORIALS UI</b><br><span style="color:#65728b">Learn. Practise. Excel.</span></p></div></div>`;
 const errors=[];
 const provider=String(process.env.EMAIL_PROVIDER||'').toLowerCase();
 const useResend=provider==='resend'||(!provider&&!!(process.env.RESEND_API_KEY&&process.env.RESEND_FROM));
 const useSmtp=provider==='smtp'||!!(process.env.SMTP_USER||process.env.SMTP_USERNAME||process.env.GMAIL_USER);
 // Resend is attempted first when selected/configured; Gmail SMTP is the automatic fallback.
 if(useResend&&process.env.RESEND_API_KEY&&process.env.RESEND_FROM){
  try{
   const response=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:'Bearer '+process.env.RESEND_API_KEY,'Content-Type':'application/json'},body:JSON.stringify({from:process.env.RESEND_FROM,to:[student.email],subject,html}),signal:AbortSignal.timeout(20000)});
   const payload=await response.json().catch(()=>({}));
   if(response.ok){console.info('Registration email sent through Resend:',payload.id||'accepted');return {sent:true,provider:'Resend'};}
   errors.push('Resend HTTP '+response.status+': '+(payload.message||payload.error||'request rejected'));
  }catch(e){errors.push('Resend: '+e.message);}
 }
 const smtpUser=process.env.SMTP_USER||process.env.SMTP_USERNAME||process.env.GMAIL_USER;
 const smtpPass=String(process.env.SMTP_PASS||process.env.SMTP_PASSWORD||process.env.SMTP_APP_PASSWORD||process.env.GMAIL_APP_PASSWORD||'').replace(/\s/g,'');
 if((useSmtp||(!provider&&smtpUser&&smtpPass))&&smtpUser&&smtpPass){
  if(!nodemailer)throw new Error('Gmail SMTP credentials are configured, but Nodemailer is unavailable.');
  const host=process.env.SMTP_HOST||'smtp.gmail.com';
  const port=Number(process.env.SMTP_PORT||465);
  if(!Number.isInteger(port)||port<1||port>65535)throw new Error('SMTP_PORT must be a valid port number.');
  const transporter=nodemailer.createTransport({host,port,secure:process.env.SMTP_SECURE?String(process.env.SMTP_SECURE).toLowerCase()==='true':port===465,auth:{user:smtpUser,pass:smtpPass},connectionTimeout:15000,greetingTimeout:15000,socketTimeout:20000,tls:{minVersion:'TLSv1.2'}});
  try{
   await transporter.verify();
   const info=await transporter.sendMail({from:process.env.SMTP_FROM||smtpUser,to:student.email,subject,html});
   console.info('Registration email sent through Gmail SMTP:',info.messageId||'accepted');
   return {sent:true,provider:'Gmail SMTP'};
  }catch(e){errors.push('Gmail SMTP: '+e.message);throw new Error(errors.join(' | '));}
  finally{transporter.close();}
 }
 if(errors.length)throw new Error(errors.join(' | '));
 if(provider==='smtp'&&!smtpUser)throw new Error('EMAIL_PROVIDER is set to smtp, but SMTP_USER is missing.');
 if(provider==='resend'&&(!process.env.RESEND_API_KEY||!process.env.RESEND_FROM))throw new Error('EMAIL_PROVIDER is set to resend, but RESEND_API_KEY or RESEND_FROM is missing.');
 console.warn('Registration email not sent: configure RESEND_API_KEY + RESEND_FROM or SMTP_USER + SMTP_PASS in Render.');
 return {sent:false,provider:null};
}
