app.get('/admin',admin,async(req,res)=>{try{await q("UPDATE students SET status='Expired' WHERE status='Active' AND expiry_date<CURRENT_DATE");const search=clean(req.query.q,100),status=['Pending','Approved','Rejected'].includes(req.query.status)?req.query.status:'';const args=[];let where='TRUE';if(status){args.push(status);where+=` AND p.status=$${args.length}`;}if(search){args.push('%'+search+'%');where+=` AND (s.full_name ILIKE $${args.length} OR s.matric ILIKE $${args.length} OR s.email ILIKE $${args.length} OR p.reference ILIKE $${args.length})`;}const payments=(await q(`SELECT p.*,s.full_name,s.matric,s.email,s.phone,s.department,s.level,s.plan FROM payments p JOIN students s ON s.id=p.student_id WHERE ${where} ORDER BY CASE p.status WHEN 'Pending' THEN 0 ELSE 1 END,p.id DESC LIMIT 250`,args)).rows;const students=(await q('SELECT * FROM students ORDER BY id DESC')).rows;const stats=(await q("SELECT (SELECT COUNT(*) FROM students) AS students,(SELECT COUNT(*) FROM payments WHERE status='Pending') AS pending,(SELECT COUNT(*) FROM students WHERE status='Active') AS active,(SELECT COUNT(*) FROM students WHERE status='Expired') AS expired")).rows[0];const prows=payments.map(p=>`<tr><td><b>${esc(p.full_name)}</b><small>${esc(p.matric)} · ${esc(p.department)} · ${esc(p.level)}</small><small>${esc(p.email)} · ${esc(p.phone)}</small></td><td>${money(p.amount)}<small>${esc(p.plan)} · ${esc(p.reference)}</small></td><td>${date(p.submitted_at)}</td><td><a href="/admin/evidence/${p.id}" target="_blank">View receipt ↗</a></td><td>${p.status==='Pending'?`<form class="review" method="post" action="/admin/payments/${p.id}/approve">${p.plan==='Semester'?`<label>Expiry date<input type="date" name="expiry_date" min="${today()}" required></label>`:''}<input name="note" placeholder="Optional note" maxlength="200"><button class="btn compact">Approve</button></form><form class="review" method="post" action="/admin/payments/${p.id}/reject"><input name="note" placeholder="Reason for rejection" maxlength="200" required><button class="btn danger compact">Reject</button></form>`:`<span class="pill ${p.status.toLowerCase()}">${p.status}</span><small>${esc(p.admin_note||'')}</small>`}<form method="post" action="/admin/payments/${p.id}/delete" onsubmit="return confirm('Permanently delete this payment record and uploaded receipt?')"><button class="btn danger compact" type="submit">Delete record</button></form></td></tr>`).join('');const supportItems=(await q(`SELECT r.*,s.full_name,s.matric FROM support_requests r JOIN students s ON s.id=r.student_id ORDER BY r.created_at DESC LIMIT 100`)).rows;const srows=students.map(s=>`<tr><td><b>${esc(s.full_name)}</b><small>${esc(s.matric)} · ${esc(s.email)}</small></td><td>${esc(s.courses)}</td><td>${esc(s.plan)}</td><td><span class="pill ${s.status.toLowerCase().replaceAll(' ','-')}">${esc(s.status)}</span></td><td>${date(s.expiry_date)}</td><td><form method="post" action="/admin/students/${s.id}/delete" onsubmit="return confirm('PERMANENTLY delete this student account, payment history, uploaded receipts and support requests? This cannot be undone.')"><button class="btn danger compact" type="submit">Delete student</button></form></td></tr>`).join('');const view=['overview','payments','materials','community','support','students'].includes(req.query.view)?req.query.view:'overview';
 page(req,res,'Admin dashboard',`${portalNav([['Overview','/admin?view=overview','⌂'],['Payments','/admin?view=payments','₦'],['Materials','/admin?view=materials','▤'],['Announcements & schedule','/admin?view=community','▦'],['Support requests','/admin?view=support','?'],['Students','/admin?view=students','♙']],view)}<div class="portal-view ${view==="overview"?"is-active":""}" data-view="overview"><section class="dashhead" id="admin-overview"><div><span class="eyebrow">PRIVATE ADMINISTRATION</span><h1>Student <em>overview.</em></h1><p>Review receipts before approving subscriptions.</p></div>${btn('Export CSV','/admin/export.csv')}</section><div class="stats"><article class="stat"><small>Total students</small><h3>${stats.students}</h3><span class="stat-note">All registered accounts</span></article><article class="stat"><small>Pending payments</small><h3>${stats.pending}</h3><span class="stat-note">Awaiting review</span></article><article class="stat"><small>Active subscriptions</small><h3>${stats.active}</h3><span class="stat-note">Currently active</span></article><article class="stat"><small>Expired subscriptions</small><h3>${stats.expired}</h3><span class="stat-note">Require renewal</span></article></div><section class="panel analytics-panel"><div class="dashhead"><div><span class="eyebrow">LIVE PORTAL SNAPSHOT</span><h2 style="margin:5px 0">Student analytics</h2><p style="color:var(--muted);margin:0">A quick view of registration and subscription activity.</p></div><span class="pill approved">Database overview</span></div><div class="analytics-grid"><div class="analytics-item"><div class="analytics-label"><span>Active subscriptions</span><b>${stats.active}</b></div><div class="analytics-track"><i style="width:${stats.students?Math.min(100,Number(stats.active)/Number(stats.students)*100):0}%"></i></div></div><div class="analytics-item"><div class="analytics-label"><span>Expired subscriptions</span><b>${stats.expired}</b></div><div class="analytics-track gold"><i style="width:${stats.students?Math.min(100,Number(stats.expired)/Number(stats.students)*100):0}%"></i></div></div><div class="analytics-item"><div class="analytics-label"><span>Pending payment queue</span><b>${stats.pending}</b></div><div class="analytics-track pink"><i style="width:${stats.students?Math.min(100,Number(stats.pending)/Number(stats.students)*100):0}%"></i></div></div></div><p class="analytics-foot">Bars show each count as a proportion of all registered students. Figures update when the dashboard is refreshed.</p></section></div><div class="portal-view ${view==="payments"?"is-active":""}" data-view="payments"><section class="panel" id="admin-payments"><h2>Payment queue</h2><form class="filter" method="get"><input type="hidden" name="view" value="payments"><input name="q" value="${esc(search)}" placeholder="Search name, matric, Gmail or reference"><select name="status"><option value="">All statuses</option>${['Pending','Approved','Rejected'].map(x=>`<option ${status===x?'selected':''}>${x}</option>`).join('')}</select><button class="btn">Filter</button></form><div class="tablewrap"><table><thead><tr><th>Student</th><th>Payment</th><th>Submitted</th><th>Receipt</th><th>Review</th></tr></thead><tbody>${prows||'<tr><td colspan="5">No matching payment submissions.</td></tr>'}</tbody></table></div></section></div><div class="portal-view ${view==="materials"?"is-active":""}" data-view="materials"><section class="panel" id="admin-materials"><h2>Learning materials management</h2><p class="formfoot">Upload a resource once and make it available in the student portal. Maximum file size: 20 MB.</p><form method="post" action="/admin/materials" enctype="multipart/form-data"><div class="profile-grid"><div class="field"><label>Material title</label><input name="title" maxlength="160" required placeholder="e.g. Introduction to bending stress"></div><div class="field"><label>Course</label><select name="course" required>${courses.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Category</label><select name="category" required>${materialCategories.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>File (PDF, Office, JPG or PNG; max 20 MB)</label><input name="material" type="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.jpg,.jpeg,.png" required></div></div><div class="field"><label>Description</label><textarea name="description" maxlength="700" rows="2" placeholder="Briefly describe this resource"></textarea></div><button class="btn">Publish material</button></form></section><section class="panel"><h2>Published materials</h2><div class="tablewrap"><table><thead><tr><th>Title</th><th>Course / category</th><th>Uploaded</th><th>Action</th></tr></thead><tbody>${(await q('SELECT id,title,course,category,created_at FROM learning_materials ORDER BY created_at DESC LIMIT 100')).rows.map(m=>`<tr><td>${esc(m.title)}</td><td>${esc(m.course)}<small>${esc(m.category)}</small></td><td>${date(m.created_at)}</td><td><form method="post" action="/admin/materials/${m.id}/delete" onsubmit="return confirm('Delete this material?')"><button class="btn danger compact">Delete</button></form></td></tr>`).join('')||'<tr><td colspan="4">No materials uploaded yet.</td></tr>'}</tbody></table></div></section></div><div class="portal-view ${view==="community"?"is-active":""}" data-view="community"><section class="panel" id="community"><h2>Announcements and tutorial schedule</h2><div class="formlayout" style="padding:0;gap:20px"><form method="post" action="/admin/announcements"><h3>Publish announcement</h3><div class="field"><label>Title</label><input name="title" maxlength="160" required></div><div class="field"><label>Message</label><textarea name="body" rows="4" maxlength="1500" required></textarea></div><button class="btn">Publish announcement</button></form><form method="post" action="/admin/classes"><h3>Schedule a tutorial</h3><div class="field"><label>Class title</label><input name="title" maxlength="160" required></div><div class="field"><label>Course</label><select name="course">${courses.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Date</label><input type="date" name="class_date" min="${today()}" required></div><div class="field"><label>Time</label><input name="class_time" maxlength="60" required placeholder="e.g. 4:00 PM"></div><div class="field"><label>Venue / meeting link</label><input name="venue" maxlength="160" required></div><div class="field"><label>Additional details</label><textarea name="details" rows="2" maxlength="500"></textarea></div><button class="btn">Publish tutorial schedule</button></form></div><h3>Published announcements</h3><div class="tablewrap"><table><thead><tr><th>Announcement</th><th>Published</th><th>Action</th></tr></thead><tbody>${(await q('SELECT id,title,created_at FROM announcements ORDER BY created_at DESC LIMIT 100')).rows.map(a=>`<tr><td><b>${esc(a.title)}</b></td><td>${date(a.created_at)}</td><td><form method="post" action="/admin/announcements/${a.id}/delete" onsubmit="return confirm('Delete this announcement?')"><button class="btn danger compact">Delete</button></form></td></tr>`).join('')||'<tr><td colspan="3">No announcements published.</td></tr>'}</tbody></table></div><h3 style="margin-top:26px">Scheduled tutorials</h3><div class="tablewrap"><table><thead><tr><th>Class</th><th>Date and time</th><th>Venue</th><th>Action</th></tr></thead><tbody>${(await q('SELECT id,title,course,class_date,class_time,venue FROM tutorial_classes ORDER BY class_date DESC,class_time LIMIT 150')).rows.map(c=>`<tr><td><b>${esc(c.title)}</b><small>${esc(c.course)}</small></td><td>${date(c.class_date)}<small>${esc(c.class_time)}</small></td><td>${esc(c.venue)}</td><td><form method="post" action="/admin/classes/${c.id}/delete" onsubmit="return confirm('Delete this scheduled tutorial?')"><button class="btn danger compact">Delete</button></form></td></tr>`).join('')||'<tr><td colspan="4">No tutorials scheduled.</td></tr>'}</tbody></table></div></section></div><div class="portal-view ${view==="support"?"is-active":""}" data-view="support"><section class="panel" id="admin-support"><h2>Student academic support requests</h2><div class="tablewrap"><table><thead><tr><th>Student</th><th>Question</th><th>Submitted</th><th>Status</th><th>Action</th></tr></thead><tbody>${supportItems.map(r=>`<tr><td><b>${esc(r.full_name)}</b><small>${esc(r.matric)}</small></td><td><b>${esc(r.subject)}</b><small>${esc(r.message)}</small></td><td>${date(r.created_at)}</td><td><span class="pill">${esc(r.status)}</span></td><td><div class="admin-actions">${r.status==='Open'?`<form method="post" action="/admin/support/${r.id}/resolve"><button class="btn compact">Mark resolved</button></form>`:''}<form method="post" action="/admin/support/${r.id}/delete" onsubmit="return confirm('Permanently delete this support request?')"><button class="btn danger compact">Delete</button></form></div></td></tr>`).join('')||'<tr><td colspan="5">No student questions yet.</td></tr>'}</tbody></table></div></section></div><div class="portal-view ${view==="students"?"is-active":""}" data-view="students"><section class="panel" id="admin-students"><h2>Registered students</h2><div class="tablewrap"><table><thead><tr><th>Student</th><th>Courses</th><th>Plan</th><th>Status</th><th>Expiry</th><th>Account action</th></tr></thead><tbody>${srows||'<tr><td colspan="6">No students registered.</td></tr>'}</tbody></table></div></section></div>`);}catch(e){console.error(e);page(req,res,'Admin error','<h2>Could not load the admin dashboard.</h2>',500);}});
app.post('/admin/students/:id/delete',admin,async(req,res)=>{const id=Number(req.params.id);if(!Number.isSafeInteger(id)||id<1){flash(req,'error','Invalid student account.');return res.redirect('/admin');}const client=await pool.connect();try{await client.query('BEGIN');const student=(await client.query('SELECT id,full_name,matric,email FROM students WHERE id=$1 FOR UPDATE',[id])).rows[0];if(!student){await client.query('ROLLBACK');flash(req,'error','Student account was not found.');return res.redirect('/admin');}const receiptPaths=(await client.query('SELECT storage_path FROM payments WHERE student_id=$1 AND storage_path IS NOT NULL',[id])).rows;if(receiptPaths.length){const c=storageConfig();for(const item of receiptPaths)await storageRequest('DELETE','/object/'+encodeURIComponent(c.bucket)+'/'+item.storage_path.split('/').map(encodeURIComponent).join('/'));}await client.query('DELETE FROM students WHERE id=$1',[id]);await client.query('INSERT INTO audit_log(actor,action,target,details) VALUES($1,$2,$3,$4)',['admin:'+req.session.user.id,'student_permanently_deleted',String(id),'Student account and linked payment receipts/support requests deleted']);await client.query('COMMIT');flash(req,'success',`Student account ${student.matric} and its linked records were permanently deleted.`);}catch(e){await client.query('ROLLBACK');console.error(e);flash(req,'error','Could not delete the student account. No records were intentionally removed.');}finally{client.release();}res.redirect('/admin');});
app.post('/admin/announcements/:id/delete',admin,async(req,res)=>{try{const r=await q('DELETE FROM announcements WHERE id=$1',[Number(req.params.id)]);flash(req,r.rowCount?'success':'error',r.rowCount?'Announcement deleted.':'Announcement not found.');}catch(e){console.error(e);flash(req,'error','Could not delete announcement.');}res.redirect('/admin#community');});
app.post('/admin/classes/:id/delete',admin,async(req,res)=>{try{const r=await q('DELETE FROM tutorial_classes WHERE id=$1',[Number(req.params.id)]);flash(req,r.rowCount?'success':'error',r.rowCount?'Tutorial schedule deleted.':'Tutorial schedule not found.');}catch(e){console.error(e);flash(req,'error','Could not delete tutorial schedule.');}res.redirect('/admin#community');});
app.post('/admin/support/:id/delete',admin,async(req,res)=>{try{const r=await q('DELETE FROM support_requests WHERE id=$1',[Number(req.params.id)]);flash(req,r.rowCount?'success':'error',r.rowCount?'Support request deleted.':'Support request not found.');}catch(e){console.error(e);flash(req,'error','Could not delete support request.');}res.redirect('/admin');});
app.post('/admin/payments/:id/delete',admin,async(req,res)=>{try{const old=(await q('SELECT storage_path FROM payments WHERE id=$1',[Number(req.params.id)])).rows[0];if(old?.storage_path){const c=storageConfig();await storageRequest('DELETE','/object/'+encodeURIComponent(c.bucket)+'/'+old.storage_path.split('/').map(encodeURIComponent).join('/'));}const r=await q('DELETE FROM payments WHERE id=$1',[Number(req.params.id)]);flash(req,r.rowCount?'success':'error',r.rowCount?'Payment record and uploaded receipt deleted.':'Payment record not found.');}catch(e){console.error(e);flash(req,'error','Could not delete payment record.');}res.redirect('/admin');});
app.get('/admin/evidence/:id',admin,async(req,res)=>{try{const p=(await q('SELECT evidence_data,evidence_type,storage_path FROM payments WHERE id=$1',[Number(req.params.id)])).rows[0];if(!p)return page(req,res,'Not found','<h2>Receipt not found.</h2>',404);if(p.storage_path){const c=storageConfig(),d=await storageRequest('POST','/object/sign/'+encodeURIComponent(c.bucket)+'/'+p.storage_path.split('/').map(encodeURIComponent).join('/'),{expiresIn:120});const signed=d.signedURL||d.signedUrl||d.url;if(!signed)throw new Error('Supabase did not return a signed file URL.');return res.redirect(/^https?:\/\//i.test(signed)?signed:c.url+'/storage/v1'+(String(signed).startsWith('/')?signed:'/'+signed));}res.setHeader('Content-Type',p.evidence_type);res.setHeader('Content-Disposition','inline');res.setHeader('X-Content-Type-Options','nosniff');res.send(p.evidence_data);}catch(e){console.error(e);page(req,res,'Error','<h2>Could not retrieve receipt.</h2>',500);}});
app.post('/admin/payments/:id/approve',admin,async(req,res)=>{try{const p=(await q('SELECT p.*,s.plan FROM payments p JOIN students s ON s.id=p.student_id WHERE p.id=$1',[Number(req.params.id)])).rows[0];if(!p||p.status!=='Pending'){flash(req,'error','This payment is no longer pending.');return res.redirect('/admin');}let expiry;if(p.plan==='Monthly'){const d=new Date();d.setDate(d.getDate()+31);expiry=d.toISOString().slice(0,10);}else{expiry=clean(req.body.expiry_date,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(expiry)||expiry<today()){flash(req,'error','Choose a valid semester expiry date.');return res.redirect('/admin');}}const client=await pool.connect();try{await client.query('BEGIN');await client.query("UPDATE payments SET status='Approved',reviewed_at=NOW(),reviewed_by=$1,admin_note=$2,expiry_date=$3 WHERE id=$4",[req.session.user.email,clean(req.body.note,200),expiry,p.id]);await client.query("UPDATE students SET status='Active',expiry_date=$1 WHERE id=$2",[expiry,p.student_id]);await client.query('COMMIT');}catch(e){await client.query('ROLLBACK');throw e;}finally{client.release();}await audit('admin:'+req.session.user.id,'payment_approved',p.id,'expiry='+expiry);flash(req,'success','Payment approved. Subscription is now active.');res.redirect('/admin');}catch(e){console.error(e);flash(req,'error','Could not approve this payment.');res.redirect('/admin');}});
app.post('/admin/payments/:id/reject',admin,async(req,res)=>{try{const p=(await q('SELECT * FROM payments WHERE id=$1',[Number(req.params.id)])).rows[0],note=clean(req.body.note,200);if(!p||p.status!=='Pending'||!note){flash(req,'error','A pending payment and rejection reason are required.');return res.redirect('/admin');}await q("UPDATE payments SET status='Rejected',reviewed_at=NOW(),reviewed_by=$1,admin_note=$2 WHERE id=$3",[req.session.user.email,note,p.id]);await q("UPDATE students SET status=CASE WHEN expiry_date>=CURRENT_DATE THEN status ELSE 'No subscription' END WHERE id=$1",[p.student_id]);await audit('admin:'+req.session.user.id,'payment_rejected',p.id,note);flash(req,'success','Payment rejected. The reason is saved.');res.redirect('/admin');}catch(e){console.error(e);flash(req,'error','Could not reject payment.');res.redirect('/admin');}});
app.get('/materials',studentOnly,async(req,res)=>{try{
 const course= courses.includes(req.query.course)?req.query.course:'';
 const args=[];let where='TRUE';if(course){args.push(course);where=`course=$1`;}
 const mats=(await q(`SELECT id,title,course,category,description,file_name,file_size,created_at FROM learning_materials WHERE ${where} ORDER BY created_at DESC`,args)).rows;
 const tabs=`<nav class="course-tabs"><a class="${!course?'active':''}" href="/materials">All courses</a>${courses.map(c=>`<a class="${course===c?'active':''}" href="/materials?course=${encodeURIComponent(c)}">${esc(c)}</a>`).join('')}</nav>`;
 const cards=mats.map(m=>`<article class="material-card"><div class="material-icon">▤</div><div><h3>${esc(m.title)}</h3><div class="meta">${esc(m.course)} · ${esc(m.category)} · ${date(m.created_at)} · ${(m.file_size/1024).toFixed(0)} KB</div><p>${esc(m.description||'Learning resource uploaded by FOCUS TUTORIALS UI.')}</p><div class="material-actions"><a class="btn small" href="/materials/${m.id}/download">Download</a><a class="btn small secondary" href="/materials/${m.id}/view" target="_blank">Preview</a></div></div></article>`).join('');
 page(req,res,'Learning materials',`<section class="dashhead"><div><span class="eyebrow">FOCUS LEARNING HUB</span><h1>Academic <em>materials.</em></h1><p>Explore resources shared by your tutors.</p></div>${btn('Back to dashboard','/dashboard','btn secondary')}</section>${tabs}<div class="material-grid">${cards||'<p class="notice">No materials are available in this course yet.</p>'}</div>`);
 }catch(e){console.error(e);page(req,res,'Error','<h2>Could not load materials.</h2>',500);}});
app.get('/materials/:id/:action',studentOnly,async(req,res)=>{try{
 if(!['view','download'].includes(req.params.action))return page(req,res,'Not found','<h2>Resource not found.</h2>',404);
 const m=(await q('SELECT * FROM learning_materials WHERE id=$1',[Number(req.params.id)])).rows[0];if(!m)return page(req,res,'Not found','<h2>Resource not found.</h2>',404);
 res.setHeader('Content-Type',m.mime_type);res.setHeader('X-Content-Type-Options','nosniff');
 const safeName=m.file_name.replace(/[\r\n"]/g,'_');res.setHeader('Content-Disposition',`${req.params.action==='view'?'inline':'attachment'}; filename="${safeName}"`);if(m.storage_path){const c=storageConfig(),d=await storageRequest('POST','/object/sign/'+encodeURIComponent(c.bucket)+'/'+m.storage_path.split('/').map(encodeURIComponent).join('/'),{expiresIn:120, ...(req.params.action==='download'?{download:true}:{})});const signed=d.signedURL||d.signedUrl||d.url;if(!signed)throw new Error('Supabase did not return a signed file URL.');return res.redirect(/^https?:\/\//i.test(signed)?signed:c.url+'/storage/v1'+(String(signed).startsWith('/')?signed:'/'+signed));}res.send(m.file_data);
 }catch(e){console.error(e);page(req,res,'Error','<h2>Could not retrieve this resource.</h2>',500);}});
app.post('/support',studentOnly,async(req,res)=>{try{const subject=clean(req.body.subject,120),message=clean(req.body.message,2000);if(!subject||!message){flash(req,'error','Please complete both fields.');return res.redirect('/dashboard');}await q('INSERT INTO support_requests(student_id,subject,message) VALUES($1,$2,$3)',[req.session.user.id,subject,message]);await audit('student:'+req.session.user.id,'support_request','student',subject);flash(req,'success','Your question has been sent to the FOCUS team.');res.redirect('/dashboard');}catch(e){console.error(e);flash(req,'error','Could not submit your question.');res.redirect('/dashboard');}});
app.post('/admin/materials',admin,(req,res)=>materialUpload.single('material')(req,res,async err=>{try{
 if(err){flash(req,'error',err.message||'Material upload failed.');return res.redirect('/admin#materials');}
 const title=clean(req.body.title,160),course=clean(req.body.course,100),category=clean(req.body.category,60),description=clean(req.body.description,700);
 if(!req.file||!title||!courses.includes(course)||!materialCategories.includes(category)){flash(req,'error','Complete the material details and attach a supported file.');return res.redirect('/admin#materials');}
 await q('INSERT INTO learning_materials(title,course,category,description,file_name,mime_type,file_data,file_size,uploaded_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)',[title,course,category,description,req.file.originalname,req.file.mimetype,req.file.buffer,req.file.size,req.session.user.email]);
 await audit('admin:'+req.session.user.id,'material_uploaded',title,course);flash(req,'success','Material published successfully to the student library.');res.redirect('/admin#materials');
 }catch(e){console.error(e);flash(req,'error','Could not publish the material.');res.redirect('/admin#materials');}}));
app.post('/admin/materials/:id/delete',admin,async(req,res)=>{try{const old=(await q('SELECT storage_path FROM learning_materials WHERE id=$1',[Number(req.params.id)])).rows[0];if(old?.storage_path){const c=storageConfig();await storageRequest('DELETE','/object/'+encodeURIComponent(c.bucket)+'/'+old.storage_path.split('/').map(encodeURIComponent).join('/'));}await q('DELETE FROM learning_materials WHERE id=$1',[Number(req.params.id)]);await audit('admin:'+req.session.user.id,'material_deleted',req.params.id);flash(req,'success','Material removed from the student library.');}catch(e){console.error(e);flash(req,'error','Could not delete material.');}res.redirect('/admin#materials');});
app.post('/admin/support/:id/resolve',admin,async(req,res)=>{try{await q("UPDATE support_requests SET status='Resolved' WHERE id=$1",[Number(req.params.id)]);await audit('admin:'+req.session.user.id,'support_resolved',req.params.id);flash(req,'success','Support request marked as resolved.');}catch(e){console.error(e);flash(req,'error','Could not update support request.');}res.redirect('/admin');});
app.post('/admin/announcements',admin,async(req,res)=>{try{const title=clean(req.body.title,160),body=clean(req.body.body,1500);if(!title||!body)throw new Error('Complete the announcement.');await q('INSERT INTO announcements(title,body) VALUES($1,$2)',[title,body]);await audit('admin:'+req.session.user.id,'announcement_published',title);flash(req,'success','Announcement published.');}catch(e){flash(req,'error',e.message||'Could not publish announcement.');}res.redirect('/admin#community');});
app.post('/admin/classes',admin,async(req,res)=>{try{const title=clean(req.body.title,160),course=clean(req.body.course,100),classDate=clean(req.body.class_date,10),time=clean(req.body.class_time,60),venue=clean(req.body.venue,160),details=clean(req.body.details,500);const parsedDate=new Date(classDate+'T12:00:00');if(!title||!courses.includes(course)||!/^\d{4}-\d{2}-\d{2}$/.test(classDate)||Number.isNaN(parsedDate.getTime())||parsedDate.toISOString().slice(0,10)!==classDate||!time||!venue)throw new Error('Complete all required class details with a valid calendar date.');await q('INSERT INTO tutorial_classes(title,course,class_date,class_time,venue,details) VALUES($1,$2,$3,$4,$5,$6)',[title,course,classDate,time,venue,details]);await audit('admin:'+req.session.user.id,'class_scheduled',title);flash(req,'success','Tutorial class scheduled.');}catch(e){flash(req,'error',e.message||'Could not schedule class.');}res.redirect('/admin#community');});
app.get('/admin/export.csv',admin,async(req,res)=>{try{const rows=(await q(`SELECT s.full_name,s.matric,s.email,s.phone,s.department,s.level,s.courses,s.plan,s.status,s.expiry_date,s.created_at,p.amount,p.reference,p.status AS payment_status,p.submitted_at,p.reviewed_at,p.reviewed_by,p.admin_note FROM students s LEFT JOIN payments p ON p.student_id=s.id ORDER BY s.id DESC,p.id DESC`)).rows;const cols=['full_name','matric','email','phone','department','level','courses','plan','status','expiry_date','created_at','amount','reference','payment_status','submitted_at','reviewed_at','reviewed_by','admin_note'];const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv=[cols.join(','),...rows.map(r=>cols.map(c=>quote(r[c])).join(','))].join('\r\n');await audit('admin:'+req.session.user.id,'csv_exported','students','rows='+rows.length);res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition','attachment; filename="focus-tutorials-students.csv"');res.send('\uFEFF'+csv);}catch(e){console.error(e);page(req,res,'Export error','<h2>Could not export the student list.</h2>',500);}});
app.use((req,res)=>page(req,res,'Page not found','<section class="panel"><h1>Page not found</h1><p>We could not find that page.</p><a class="btn" href="/">Return home</a></section>',404));
app.use((err,req,res,next)=>{console.error(err);if(res.headersSent)return next(err);page(req,res,'Something went wrong',`<section class="panel"><h1>Something went wrong</h1><p>${esc(err.message||'Please try again later.')}</p></section>`,500);});
// Initialize once per warm process. Vercel imports this module as a serverless handler;
// local development still starts a normal HTTP server.
const ready=init();
if(require.main===module){
 ready.then(()=>app.listen(PORT,()=>console.log('FOCUS TUTORIALS UI running on port '+PORT)))
  .catch(e=>{console.error('Database initialization failed:',e);process.exit(1);});
}
module.exports={app,ready,pool};

